from vA import CHARSET_CAVEAT, COERCE_CAVEAT
WINDOW_CAVEAT = ("The optional [start end] window is supported and clamps rather than raising: indices outside the "
  "string are pulled to the ends, and a window with start greater than end is treated as empty. SRFI-13 requires "
  "0 <= start <= end <= |s| and leaves violations an error, so code that relies on the clamping is Motoi-specific.")

